import React, { useEffect, useState } from 'react';
import './App.css';

function App() {
  const [movies, setMovies] = useState([]);
  const [selectedMovie, setSelectedMovie] = useState(null);
  const cors = require('cors'); app.use(cors());

  // Fetch all movies
  useEffect(() => {
    fetch('http://localhost:4000/api/movies')

      .then(res => res.json())
      .then(data => {
        console.log("Fetched movies:", data);
        if (Array.isArray(data)) {
          setMovies(data);
        } else if (data.movies) {
          setMovies(data.movies);
        } else {
          console.error("Unexpected data format:", data);
        }
      })
      .catch(err => console.error("Error fetching movies:", err));
  }, []);

  // Detail view
  if (selectedMovie) {
    return (
      <div className="movie-detail">
        <h2>{selectedMovie.title}</h2>
        <p><strong>Tagline:</strong> {selectedMovie.tagline}</p>
        <p><strong>Overview:</strong> {selectedMovie.overview}</p>
        <p>
          <strong>Release Date:</strong>{" "}
          {selectedMovie.release_date
            ? new Date(selectedMovie.release_date).toLocaleDateString()
            : "Not available"}
        </p>
        <p><strong>Runtime:</strong> {selectedMovie.runtime} minutes</p>
        <p><strong>Vote Average:</strong> {selectedMovie.vote_average}/10</p>
        <button onClick={() => setSelectedMovie(null)}>Back to list</button>
      </div>
    );
  }

  // List view
  return (
    <div className="movie-list">
      {movies.length === 0 ? (
        <p>No movies loaded</p>
      ) : (
        movies.map(m => (
          <div
            key={m.id}
            className="movie-card"
            onClick={() => {
              fetch(`http://localhost:4000/api/movies/${m.id}`)
                .then(res => res.json())
                .then(data => setSelectedMovie(data))
                .catch(err => console.error("Error fetching movie:", err));
            }}
          >
            <h3>{m.title}</h3>
            <p>{m.tagline || "No tagline"}</p>
            <p>⭐ {m.vote_average}/10</p>
          </div>
        ))
      )}
    </div>
  );
}

export default App;
